package com.enterprise.siem.config;
import com.enterprise.siem.detection.*; import com.enterprise.siem.model.Severity; import com.fasterxml.jackson.databind.*; import com.fasterxml.jackson.dataformat.yaml.YAMLFactory; import java.io.*; import java.nio.file.*; import java.util.*;
public final class RuleConfigLoader { private RuleConfigLoader(){} public static List<DetectionRule> load(String path) throws IOException { JsonNode root; try(InputStream input=Files.newInputStream(Path.of(path))){root=new ObjectMapper(new YAMLFactory()).readTree(input);} if(root==null||!root.path("rules").isArray())throw new IOException("rules must be an array"); List<DetectionRule> result=new ArrayList<>(); for(JsonNode n:root.path("rules")){if(!n.isObject()||!n.hasNonNull("id"))throw new IOException("rule id is required");String id=n.path("id").asText(); if(!known(id))throw new IOException("unknown rule id: "+id); boolean enabled=booleanValue(n,"enabled",true);int threshold=intValue(n,"threshold",id.equals("SUSPICIOUS-LOGIN")?3:5);long seconds=longValue(n,"windowSeconds",60);Severity severity=severity(n.path("severity").asText(defaultSeverity(id)));if(threshold<=0||seconds<=0)throw new IOException("rule "+id+" has non-positive limits"); if(!enabled)continue;switch(id){case "SSH-BRUTE-FORCE"->result.add(new BruteForceRule(threshold,seconds,severity));case "DISTRIBUTED-SSH-BRUTE-FORCE", "DISTRIBUTED-BRUTE-FORCE"->result.add(new DistributedBruteForceRule(threshold,seconds,severity,true));case "TRAFFIC-SPIKE"->result.add(new TrafficSpikeRule(threshold,seconds,severity));case "SUSPICIOUS-LOGIN"->result.add(new SuspiciousLoginRule(threshold,seconds,severity));default->throw new IOException("unknown rule id: "+id);}}return result;} private static boolean known(String id){return Set.of("SSH-BRUTE-FORCE","DISTRIBUTED-SSH-BRUTE-FORCE","DISTRIBUTED-BRUTE-FORCE","TRAFFIC-SPIKE","SUSPICIOUS-LOGIN").contains(id);} private static boolean booleanValue(JsonNode n,String key,boolean defaultValue)throws IOException{if(!n.has(key))return defaultValue;if(!n.get(key).isBoolean())throw new IOException(key+" must be boolean");return n.get(key).booleanValue();} private static int intValue(JsonNode n,String key,int defaultValue)throws IOException{if(!n.has(key))return defaultValue;if(!n.get(key).canConvertToInt())throw new IOException(key+" must be an integer");return n.get(key).intValue();} private static long longValue(JsonNode n,String key,long defaultValue)throws IOException{if(!n.has(key))return defaultValue;if(!n.get(key).canConvertToLong())throw new IOException(key+" must be an integer");return n.get(key).longValue();} private static String defaultSeverity(String id){return id.equals("DISTRIBUTED-BRUTE-FORCE")||id.equals("DISTRIBUTED-SSH-BRUTE-FORCE")?"CRITICAL":id.equals("TRAFFIC-SPIKE")?"MEDIUM":"HIGH";} private static Severity severity(String value)throws IOException{try{return Severity.valueOf(value.toUpperCase(Locale.ROOT));}catch(IllegalArgumentException e){throw new IOException("unknown severity: "+value,e);}} }
